$('#app').innerHTML=`<a class="skip" href="#article-title">Ir al artículo</a><div class="shell"><aside class="rail"><a class="brand" href="./index.html" aria-label="Mi blog">${icon('feather')}</a><nav aria-label="Blog">${button('house','Ver blog','blog')}${button('file-pen-line','Artículos y borradores','drafts')}${button('search','Buscar artículos','search')}${button('image','Insertar imagen','media')}${button('upload','Importar Markdown','import')}${button('download','Exportar artículo','export')}${button('settings-2','Configuración','settings')}${button('circle-help','Ayuda y atajos','help')}</nav>${button('square-pen','Nuevo artículo','new','class="new-post"')}<button class="avatar" data-profile="initial" data-action="settings" aria-label="Perfil y conexión">知</button></aside><aside class="articles-panel" aria-label="Artículos"><div class="articles-heading"><h1>Artículos</h1>${button('square-pen','Crear artículo','new')}</div><div class="article-tabs" role="tablist" aria-label="Estado de artículos"><button role="tab" data-action="panel-drafts" aria-selected="true">Borradores</button><button role="tab" data-action="panel-published" aria-selected="false">Publicados</button></div><div id="articles-list"></div></aside><main class="document" id="document"><div class="sticky"><header>${button('arrow-left','Mis artículos','drafts')}<div class="save-state"><span class="badge">Borrador</span><span id="saved">Guardado en este navegador</span></div><div class="header-actions"><button class="text-action" data-action="preview">Vista previa</button><button class="primary" data-action="publish">Publicar</button>${button('maximize-2','Modo enfoque','focus')}${button('ellipsis','Más opciones','more')}</div></header><div class="toolbar" role="toolbar" aria-label="Formato del artículo"><div class="format-group">${button('bold','Negrita (Ctrl+B)','bold')}${button('italic','Cursiva (Ctrl+I)','italic')}${button('strikethrough','Tachado','strike')}</div><select id="text-style" aria-label="Estilo de texto"><option value="p">Cuerpo</option><option value="1">Título grande</option><option value="2">Título</option><option value="3">Subtítulo</option></select><div class="format-group divider">${button('quote','Cita','quote')}</div><div class="format-group divider">${button('list','Lista con viñetas','bullet')}${button('list-ordered','Lista numerada','ordered')}</div><div class="format-group divider">${button('link','Enlace','link')}${button('smile','Añadir emoji','emoji')}</div><button class="insert" data-action="insert">Insertar ${icon('chevron-down')}</button><span id="word-count">0 palabras</span></div></div><div id="cover" class="cover"><button data-action="cover" aria-label="Añadir portada">${icon('image-plus')}</button><span>Recomendamos una imagen con proporción 5:2 para mejores resultados.</span></div><div class="article-content"><textarea id="article-title" rows="1" maxlength="300" placeholder="Añade un título" aria-label="Título del artículo"></textarea><div class="byline"><span class="avatar small" data-profile="initial">知</span><strong id="author" data-profile="author"></strong><span class="author-handle">@<span id="handle" data-profile="handle"></span></span></div><div id="editor"></div><textarea id="markdown-source" aria-label="Código Markdown" spellcheck="false" hidden></textarea><div id="preview" class="prose" hidden></div></div><footer class="author-footer"><a class="author-footer-link" href="./index.html" aria-label="Ver blog del autor"><span class="avatar" data-profile="initial">知</span><span><strong id="footer-author" data-profile="author"></strong><span class="author-handle">@<span id="footer-handle" data-profile="handle"></span></span><span id="footer-bio" data-profile="bio"></span></span></a></footer><div class="editor-foot"><span id="reading">1 min de lectura</span><span>Markdown compatible ${icon('check')}</span></div></main><aside class="margin-note"><span>UN ESPACIO PARA TUS IDEAS</span><p>Escribe algo que<br>merezca quedarse.</p><a href="./index.html">Visitar mi blog ↗</a></aside></div><dialog id="modal"><div class="modal-top"><h2 id="modal-title"></h2><button data-action="close" aria-label="Cerrar">${icon('x')}</button></div><div id="modal-body"></div></dialog><div id="toast" role="status" aria-live="polite"></div><input id="file-input" type="file" hidden><input id="md-input" type="file" accept=".md,.markdown,.txt,.json" hidden>`;

const Media=Node.create({name:'media',group:'block',atom:true,addAttributes(){return {src:{default:''},kind:{default:'video'}};},parseHTML(){return [{tag:'video',getAttrs:e=>({src:e.getAttribute('src'),kind:'video'})},{tag:'audio',getAttrs:e=>({src:e.getAttribute('src'),kind:'audio'})}];},renderHTML({HTMLAttributes}){return [HTMLAttributes.kind==='audio'?'audio':'video',mergeAttributes({controls:'',preload:'metadata'}, {src:HTMLAttributes.src})];},renderMarkdown(node){const tag=node.attrs.kind==='audio'?'audio':'video';return `<${tag} controls src="${esc(node.attrs.src)}"></${tag}>`;}});
const MathBlock=Node.create({name:'mathBlock',group:'block',atom:true,addAttributes(){return {latex:{default:''}};},parseHTML(){return [{tag:'div[data-latex]',getAttrs:e=>({latex:e.getAttribute('data-latex')})}];},renderHTML({HTMLAttributes}){return ['div',{'data-latex':HTMLAttributes.latex,class:'math-block'},HTMLAttributes.latex];},renderMarkdown(node){return `<div data-latex="${esc(node.attrs.latex)}" class="math-block">${esc(node.attrs.latex)}</div>`;},addNodeView(){return ({node})=>{const dom=document.createElement('div');dom.className='math-block';dom.dataset.latex=node.attrs.latex;katex.render(node.attrs.latex,dom,{throwOnError:false,displayMode:true});return {dom};};}});
function markdownWithMathBlocks(markdown){return markdown.replace(/(^|\n)[ \t]*\$\$[ \t]*\n?([\s\S]*?)\n?[ \t]*\$\$[ \t]*(?=\n|$)/g,(_match,leading,latex)=>`${leading}<div data-latex="${esc(latex.trim())}" class="math-block">${esc(latex.trim())}</div>`);}
const editor=new Editor({element:$('#editor'),extensions:[StarterKit.configure({link:{openOnClick:false,HTMLAttributes:{rel:'noopener noreferrer'}}}),Image.configure({allowBase64:true}),Placeholder.configure({placeholder:'Empieza a escribir o pega tu texto Markdown…'}),TableKit,TaskList,TaskItem.configure({nested:true}),Markdown,Media,MathBlock],content:'',editorProps:{attributes:{'aria-label':'Contenido del artículo',role:'textbox','aria-multiline':'true'},handlePaste(view,event){const text=event.clipboardData?.getData('text/plain');const files=event.clipboardData?.files;if(files?.length&&files[0].type.startsWith('image/')){readImage(files[0],false);return true;}if(text&&(/(^|\n)(#{1,6} |[-*+] |\d+\. |>|```|\|)|\*\*|\[[^\]]+\]\(|!\[|~~|\$\$/.test(text))){event.preventDefault();editor.commands.insertContent(editor.markdown.parse(markdownWithMathBlocks(text)));return true;}return false;},handleDrop(view,event){const file=event.dataTransfer?.files?.[0];if(file?.type.startsWith('image/')){event.preventDefault();readImage(file,false);return true;}return false;}},onUpdate(){scheduleSave();updateCounts();},onSelectionUpdate(){updateToolbar();}});
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('visible'),5000);}
function refreshIcons(){createIcons({icons,attrs:{'stroke-width':1.8}});}
function updateCounts(){const {words,minutes}=readingStats(editor.getText());$('#word-count').textContent=`${words} palabras`;$('#reading').textContent=`${minutes} min de lectura`;}
function updateToolbar(){for(const [a,n] of [['bold','bold'],['italic','italic'],['strike','strike'],['quote','blockquote'],['bullet','bulletList'],['ordered','orderedList']]){const b=$(`[data-action="${a}"]`);b.classList.toggle('active',editor.isActive(n));b.setAttribute('aria-pressed',editor.isActive(n));}$('#text-style').value=[1,2,3].find(level=>editor.isActive('heading',{level}))||'p';}
let saveTimeout;
function scheduleSave(){if(sourceMode){current.markdown=$('#markdown-source').value;}else {current.markdown=editor.getMarkdown();current.html=editor.getHTML();}current.title=$('#article-title').value;current.updatedAt=new Date().toISOString();$('#saved').textContent='Guardando…';clearTimeout(saveTimeout);saveTimeout=setTimeout(save,350);}
function renderArticles(){
  const list=$('#articles-list');
  if(articleTab==='draft'){list.innerHTML=draftListMarkup();updateArticleTabs();return;}
  const state=publishedLibrary.state();
  published=publishedArticles(state.posts,drafts);
  const items=articleTab==='published'?published:drafts.filter(d=>d.status!=='published');
  list.innerHTML=items.map(d=>`<button class="article-item ${d.id===current.id?'selected':''}" ${articleTab==='published'?`data-published="${published.indexOf(d)}"`:`data-draft="${esc(d.id)}"`} ${d.id===current.id?'aria-current="true"':''}><strong>${esc(d.title||'Sin título')}</strong><span>${new Date(d.updatedAt).toLocaleDateString('es-MX')}</span></button>`).join('')||`<p class="panel-empty">${articleTab==='published'?'Tus artículos publicados aparecerán aquí.':'Empieza un nuevo artículo para guardar tus ideas.'}</p>`;
  if(articleTab==='published'){
    if(state.loading)list.insertAdjacentHTML('afterbegin','<p class="panel-empty" role="status">Cargando artículos de GitHub…</p>');
    if(state.error)list.insertAdjacentHTML('afterbegin',`<div class="panel-empty" role="status"><p>${esc(state.error)}</p><button class="outline" data-action="retry-published">Reintentar</button></div>`);
    if(!items.length&&(state.loading||state.error))list.querySelector(':scope > p.panel-empty:not([role])')?.remove();
  }
  updateArticleTabs();
}
function updateArticleTabs(){for(const b of document.querySelectorAll('.article-tabs button'))b.setAttribute('aria-selected',b.dataset.action===`panel-${articleTab==='draft'?'drafts':articleTab}`);}
function save(options={}){clearTimeout(saveTimeout);syncCurrent();updateCounts();drafts=storeDraft(drafts,current,options);try{localStorage.setItem(STORAGE,JSON.stringify(drafts));$('#saved').textContent=drafts.some(d=>d.id===current.id)?'Guardado en este navegador':'Sin cambios';renderArticles();}catch{$('#saved').textContent='No se pudo guardar';toast('El almacenamiento está lleno. Exporta tu artículo para conservarlo.');}}
function syncCurrent(){if(sourceMode){current.markdown=$('#markdown-source').value;editor.commands.setContent(markdownWithMathBlocks(current.markdown),{contentType:'markdown',emitUpdate:false});current.html=editor.getHTML();}else{current.markdown=editor.getMarkdown();current.html=editor.getHTML();}current.title=$('#article-title').value;}
function load(draft){clearTimeout(saveTimeout);current={...draft};sourceMode=false;preview=false;$('#markdown-source').hidden=true;$('#editor').hidden=false;$('#preview').hidden=true;$('#article-title').readOnly=false;$('#article-title').value=current.title;resizeTitle();editor.commands.setContent(current.html||markdownWithMathBlocks(current.markdown||''),{contentType:current.html?'html':'markdown',emitUpdate:false});editor.setEditable(true,false);renderEditorProfile();renderCover();updateCounts();updateToolbar();$('.badge').textContent=current.status==='published'?'Publicado':'Borrador';$('.save-state').classList.toggle('is-published',current.status==='published');$('[data-action="publish"]').textContent=current.status==='published'?'Actualizar':'Publicar';$('[data-action="preview"]').textContent='Vista previa';$('.toolbar').classList.remove('previewing');$('#saved').textContent=drafts.some(d=>d.id===current.id)?'Guardado en este navegador':'Sin cambios';renderArticles();refreshIcons();}
function renderCover(){const cover=$('#cover');cover.style.backgroundImage=current.cover?`url("${current.cover.replace(/["\\\n\r]/g,'')}")`:'';cover.classList.toggle('has-cover',!!current.cover);cover.querySelector('span').hidden=!!current.cover;cover.querySelector('button').title=current.cover?'Cambiar portada':'Añadir portada';}
function resizeTitle(){$('#article-title').style.height='auto';$('#article-title').style.height=$('#article-title').scrollHeight+'px';}
function modal(title,body){$('#modal').classList.toggle('media-dialog',title==='Editar portada');$('#modal-title').textContent=title;$('#modal-body').innerHTML=body;$('#modal').showModal();refreshIcons();}
function close(){$('#modal').close();}
function form(title,fields,submit,onSubmit){modal(title,`<form id="dialog-form">${fields}<p class="form-error" role="alert" hidden></p><button class="primary wide" type="submit">${submit}</button></form>`);$('#dialog-form').onsubmit=async e=>{e.preventDefault();const errorBox=e.target.querySelector('.form-error');errorBox.hidden=true;try{await onSubmit(new FormData(e.target));}catch(error){errorBox.textContent=error.message;errorBox.hidden=false;toast(error.message);}};}
const field=(label,name,value='',type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
function urlForm(title,callback,kind='URL'){form(title,field(kind,'url','','url','required placeholder="https://…"')+field('Texto alternativo / descripción','alt'),'Insertar',data=>{const url=data.get('url');if(!/^https?:\/\//i.test(url))throw Error('Usa un enlace HTTPS o HTTP válido.');callback(url,data.get('alt'));close();});}
function syncSource(){if(sourceMode){editor.commands.setContent(markdownWithMathBlocks($('#markdown-source').value),{contentType:'markdown',emitUpdate:false});current.html=editor.getHTML();current.markdown=editor.getMarkdown();}else{current.html=editor.getHTML();current.markdown=editor.getMarkdown();}}
function togglePreview(){syncSource();preview=!preview;editor.setEditable(!preview);$('#editor').hidden=preview||sourceMode;$('#markdown-source').hidden=preview||!sourceMode;$('#preview').hidden=!preview;$('#article-title').readOnly=preview;$('#preview').innerHTML=DOMPurify.sanitize(editor.getHTML(),{ADD_TAGS:['video','audio'],ADD_ATTR:['controls']});$('#preview').querySelectorAll('[data-latex]').forEach(el=>katex.render(el.dataset.latex,el,{throwOnError:false,displayMode:true}));$('[data-action="preview"]').textContent=preview?'Volver a editar':'Vista previa';$('.toolbar').classList.toggle('previewing',preview);$('.badge').textContent=preview?'Vista previa':current.status==='published'?'Publicado':'Borrador';}
function exportFile(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportedHTML(){const node=document.createElement('div');node.innerHTML=DOMPurify.sanitize(editor.getHTML(),{ADD_TAGS:['video','audio'],ADD_ATTR:['controls']});node.querySelectorAll('[data-latex]').forEach(el=>el.innerHTML=katex.renderToString(el.dataset.latex,{displayMode:true,output:'mathml',throwOnError:false}));return node.innerHTML;}
function exportMenu(){syncSource();modal('Exportar artículo',`<p>Guarda una copia de tu trabajo.</p><div class="menu-list"><button data-action="export-md">${icon('file-code')} Markdown (.md)</button><button data-action="export-html">${icon('code')} Página HTML (.html)</button><button data-action="export-json">${icon('archive')} Respaldo completo (.json)</button></div>`);}
function showAppearance(){
  const prefs=appearance.get();
  const swatches=items=>items.map(c=>`<label class="color-choice" title="${c.name}" style="--swatch:${c.hex};--swatch-ink:${accentForeground(c.id)}"><input type="radio" name="appearance-color" value="${c.id}" aria-label="${c.name}" ${prefs.color===c.id?'checked':''}><span class="color-dot">${icon('check')}</span></label>`).join('');
  modal('Apariencia',`<p class="appearance-intro">Personaliza el tamaño del texto, el color y el fondo. Se aplica al editor y a la lectura del blog en este navegador.</p><div class="appearance-preview"><span class="avatar small" data-profile="initial">知</span><div><strong>${esc(settings.author)}</strong> <span>@${esc(settings.owner)}</span><p>Un espacio para tus ideas. Escribe y comparte historias que merezcan quedarse. <em>Así se verá tu color.</em></p></div></div><fieldset class="appearance-section"><legend>Tamaño de fuente</legend><div class="font-slider"><span aria-hidden="true">Aa</span><input aria-label="Tamaño de fuente" type="range" min="0" max="4" step="1" value="${prefs.size}"><span aria-hidden="true">Aa</span></div><div class="size-stops" aria-hidden="true"><span>13</span><span>14</span><span>15</span><span>17</span><span>18</span></div></fieldset><fieldset class="appearance-section"><legend>Color</legend><p class="palette-caption">Colores de X</p><div class="color-options">${swatches(PALETTE.slice(0,6))}</div><p class="palette-caption pastel">Variaciones pastel</p><div class="color-options">${swatches(PALETTE.slice(6))}</div></fieldset><fieldset class="appearance-section"><legend>Fondo</legend><div class="background-options"><label class="background-choice light"><input type="radio" name="appearance-background" value="light" ${prefs.background==='light'?'checked':''}>Predeterminado</label><label class="background-choice dark"><input type="radio" name="appearance-background" value="dark" ${prefs.background==='dark'?'checked':''}>Luces apagadas</label></div><label class="system-choice">Usar la configuración del sistema<input role="switch" type="checkbox" id="appearance-system" ${prefs.system?'checked':''}></label><p class="hint">El fondo cambiará automáticamente con el tema de tu dispositivo.</p></fieldset><div class="appearance-done"><button class="primary" data-action="close">Listo</button></div>`);
  const range=$('.font-slider input');
  range.setAttribute('aria-valuetext',`${[13,14,15,17,18][prefs.size]} píxeles`);
  const change=value=>{if(!appearance.set(value))toast('El cambio se aplicó, pero el navegador no permite guardarlo.');resizeTitle();};
  range.oninput=e=>{change({size:Number(e.target.value)});range.setAttribute('aria-valuetext',`${[13,14,15,17,18][Number(e.target.value)]} píxeles`);};
  for(const radio of document.querySelectorAll('[name="appearance-color"]'))radio.onchange=e=>change({color:e.target.value});
  for(const radio of document.querySelectorAll('[name="appearance-background"]'))radio.onchange=e=>{change({background:e.target.value,system:false});$('#appearance-system').checked=false;};
  $('#appearance-system').onchange=e=>change({system:e.target.checked});
}
function renderEditorProfile(){
  current.author=settings.author;current.authorBio=settings.bio||'';current.authorHandle=settings.handle||settings.owner;
  applyProfileDOM(document,{author:settings.author,bio:settings.bio,handle:settings.handle||settings.owner});
}
function acceptProfile(value){
  settings={...settings,author:value.author,bio:value.bio,handle:value.handle,banner:value.banner};
  localStorage.setItem('blog-studio-settings',JSON.stringify(settings));
  drafts=drafts.map(d=>({...d,author:value.author,authorBio:value.bio,authorHandle:value.handle}));
  localStorage.setItem(STORAGE,JSON.stringify(drafts));
  renderEditorProfile();
}
function renderConnectionStatus(){
  const button=$('.rail nav [data-action="settings"]');
  const card=$('#connection-status');if(card){card.outerHTML=connectionMarkup();refreshIcons();}
  button.dataset.connected=String(!!token);
  button.setAttribute('aria-description',token?'Token guardado en este navegador':'Sin token de GitHub');
  button.title=token?'Configuración · Token guardado en este navegador':'Configuración · Sin token de GitHub';
}
function connectionMarkup(){return `<div id="connection-status" class="connection-status ${token?'is-connected':''}" role="status"><span class="connection-status-icon">${icon(token?'check':'circle-help')}</span><div><strong>${token?'Token guardado en este navegador':'Sin token de GitHub'}</strong><p>${token?'Disponible para publicar. GitHub comprueba sus permisos al guardar o publicar.':'Conecta tu token para publicar artículos y actualizar tu perfil en el sitio público.'}</p></div></div>`;}
function showSettings(){
  let banner=settings.banner||'',bannerSource=banner,cropState={};
  form('Tu blog',`<button type="button" class="outline wide" data-action="appearance">Apariencia: colores, texto y fondo</button>${connectionMarkup()}<p>Tu perfil se aplica a la portada y a todos tus artículos, incluidos los ya publicados.</p><section class="blog-cover-settings" aria-label="Portada del blog"><h3>Portada del blog</h3><div id="blog-cover-preview" class="blog-cover-preview"></div><p class="hint">Esta imagen es independiente de las portadas de tus artículos. Proporción 3:1.</p><div class="blog-cover-controls"><button type="button" class="outline" id="blog-cover-upload">Subir portada</button><button type="button" class="outline" id="blog-cover-adjust">Ajustar</button><button type="button" class="outline" id="blog-cover-remove">Quitar</button></div><input type="file" id="blog-cover-file" accept="image/png,image/jpeg,image/webp,image/gif" hidden><div id="blog-cover-crop" hidden>${cropMarkup}<button type="button" class="outline" id="blog-cover-cancel">Cancelar ajuste</button></div><p id="blog-cover-error" role="alert" hidden></p></section>${field('Nombre del autor','author',settings.author,'text','required maxlength="100"')}${field('Nombre de usuario público','handle',settings.handle||settings.owner,'text','maxlength="100"')}${field('Presentación del autor y del blog','bio',settings.bio||'','text','maxlength="500"')}<p class="hint">Al guardar, los cambios aparecen en este navegador al instante. Con tu token conectado también se actualiza el sitio público cuando GitHub termina el despliegue.</p>${field('Usuario de GitHub','owner',settings.owner,'text','required')}${field('Repositorio','repo',settings.repo,'text','required')}${field('Token de GitHub','token',token,'password','autocomplete="off" placeholder="github_pat_…"')}<p class="hint">Usa un token de acceso específico para este repositorio, con permiso <b>Contents: Read and write</b>. Se guarda en este navegador y se comparte entre sus pestañas. Permanece al cerrarlo hasta que lo desconectes o borres los datos del sitio. Los borradores se guardan en este navegador.</p><a target="_blank" rel="noopener" href="https://github.com/settings/personal-access-tokens/new?name=Blog%20Studio&amp;target_name=neura-neura&amp;expires_in=90&amp;contents=write&amp;actions=read">Crear token en GitHub ↗</a><label class="check"><input type="checkbox" name="disconnect"> Desconectar y borrar el token de este navegador</label>`,'Guardar configuración',async data=>{
    const next={banner,owner:String(data.get('owner')).trim(),repo:String(data.get('repo')).trim(),author:String(data.get('author')).trim(),bio:String(data.get('bio')).trim(),handle:String(data.get('handle')).trim().replace(/^@+/, '')};
    if(!/^[\w.-]+$/.test(next.owner)||!/^[\w.-]+$/.test(next.repo))throw Error('Usuario o repositorio no válido.');
    const nextToken=data.get('disconnect')?'':String(data.get('token')).trim();
    token=tokenStore.set(nextToken);settings=next;renderConnectionStatus();
    localStorage.setItem('blog-studio-settings',JSON.stringify(settings));
    const value=blogProfile.set(settings);save();
    if(!token){close();toast('Perfil actualizado en este navegador. Conecta tu token y guarda de nuevo para actualizar el blog público.');return;}
    const submit=$('#dialog-form [type="submit"]');submit.disabled=true;submit.textContent='Actualizando perfil…';
    try{await client().saveProfile(value);blogProfile.markPublished(value);close();toast('Perfil guardado. GitHub está actualizando la portada y todos los artículos.');}
    catch(error){submit.disabled=false;submit.textContent='Reintentar actualización';throw Error('Tus datos quedaron guardados en este navegador. '+error.message);}
  });
  const preview=$('#blog-cover-preview'),crop=$('#blog-cover-crop'),upload=$('#blog-cover-file'),error=$('#blog-cover-error');
  function previewBanner(){
    preview.replaceChildren();
    if(banner){const image=document.createElement('img');image.src=banner;image.alt='Portada del blog';preview.append(image);}else preview.textContent='Sin portada';
    $('#blog-cover-adjust').hidden=!banner;$('#blog-cover-remove').hidden=!banner;
    $('#blog-cover-upload').textContent=banner?'Cambiar portada':'Subir portada';
  }
  let observer;
  function finishCrop(){crop.hidden=true;observer?.disconnect();$('#dialog-form [type="submit"]').disabled=false;}
  async function adjustBanner(){
    observer?.disconnect();crop.hidden=false;error.hidden=true;$('#dialog-form [type="submit"]').disabled=true;
    try{observer=await mountCoverCrop(crop,bannerSource,(url,state)=>{banner=url;cropState=state;finishCrop();previewBanner();},cropState,3);}
    catch(e){finishCrop();error.textContent='No pudimos abrir la imagen. Prueba con otra.';error.hidden=false;}
  }
  $('#blog-cover-upload').onclick=()=>upload.click();
  $('#blog-cover-adjust').onclick=adjustBanner;
  $('#blog-cover-remove').onclick=()=>{banner='';bannerSource='';cropState={};finishCrop();previewBanner();};
  $('#blog-cover-cancel').onclick=()=>{bannerSource=banner;cropState={};finishCrop();};
  upload.onchange=async()=>{
    const file=upload.files[0];upload.value='';if(!file)return;
    if(!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type)||file.size>2*1024*1024){error.textContent='Usa una imagen PNG, JPEG, GIF o WebP de menos de 2 MB.';error.hidden=false;return;}
    try{bannerSource=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});cropState={};await adjustBanner();}
    catch{error.textContent='No pudimos leer la imagen.';error.hidden=false;}
  };
  previewBanner();
}
function renderDraftDialog(){const list=$('#draft-list');if(list)list.innerHTML=draftListMarkup($('#draft-search')?.value||'');}
async function showDrafts(search=false){save();modal(search?'Buscar artículos':'Tus borradores',`<div class="draft-tools"><button class="outline" data-action="new">${icon('square-pen')} Nuevo artículo</button><label class="draft-search">${icon('search')}<input id="draft-search" type="search" aria-label="Buscar artículos" placeholder="Buscar por título…"></label></div><div id="draft-list"></div>`);renderDraftDialog();$('#draft-search').oninput=renderDraftDialog;if(search)$('#draft-search').focus();return privateLibrary.load();}

function client(){if(!token)throw Error('Conecta tu token de GitHub en Configuración para publicar.');return new GitHubClient({...settings,token});}
function privateClient(){if(!token)throw Error('Conecta tu token de GitHub para acceder a tus borradores en la nube.');return new PrivateDraftClient({...settings,token});}
function draftListMarkup(query=''){
  const {posts,loading,error}=privateLibrary.state();
  const entries=draftEntries(drafts,posts).filter(({draft})=>draft.title.toLowerCase().includes(query.toLowerCase()));
  return `${entries.map(({draft:d,remoteOnly,storage})=>`<button class="article-item ${d.id===current.id?'selected':''}" ${remoteOnly?`data-private="${esc(d.id)}"`:`data-draft="${esc(d.id)}"`}><strong>${esc(d.title||'Sin título')}</strong><span>${esc(storage)}</span><span>${new Date(d.updatedAt||d.privateSavedAt).toLocaleDateString('es-MX')}</span></button>`).join('')||(!loading?'<p class="panel-empty">No hay borradores que mostrar.</p>':'')}${loading?'<p class="panel-empty" role="status">Buscando borradores en la nube…</p>':''}${error?`<div class="panel-empty" role="status"><p>No se pudieron consultar los borradores en la nube. Tus borradores locales siguen disponibles.</p><button class="outline" data-action="retry-private">Reintentar</button><button class="outline" data-action="private-access">Revisar acceso</button></div>`:''}`;
}
function privateAccess(){
  modal('Acceso a borradores en la nube',`<p>Los borradores se guardan en <strong>${esc(settings.owner)}/${esc(settings.repo)}-drafts</strong>, separado del blog público.</p><ol><li>Abre tu token de Blog Studio en GitHub.</li><li>En <strong>Repository access → Only select repositories</strong>, conserva <strong>${esc(settings.repo)}</strong> y añade <strong>${esc(settings.repo)}-drafts</strong>.</li><li>En <strong>Repository permissions</strong>, usa <strong>Contents: Read and write</strong> y guarda los cambios.</li></ol><p class="hint">Puedes usar el mismo token guardado. Si generas uno nuevo, sustitúyelo en Configuración.</p><p><a href="https://github.com/settings/personal-access-tokens" target="_blank" rel="noopener noreferrer">Abrir mis tokens en GitHub ↗</a></p><button class="outline wide" data-action="settings">Configuración del blog</button>`);
}
function savePrivateDraft(){
  syncSource();save();
  if(!hasDraftContent(current)){toast('Añade un título, texto o una imagen antes de guardar una versión en la nube.');return;}
  const snapshot=structuredClone(current);
  form('Guardar borrador en la nube',`<p>Guarda el borrador en la nube para continuar desde otro dispositivo. No aparecerá en tu perfil, en el buscador del blog ni en RSS.</p><p class="hint">El guardado automático seguirá siendo local. La versión en la nube solo se actualiza cuando tú la guardas aquí.</p>${snapshot.privateSavedAt?`<p class="hint">Última versión en la nube: ${new Date(snapshot.privateSavedAt).toLocaleString('es-MX')}.</p>`:''}<button type="button" class="outline wide" data-action="private-access">Revisar acceso a borradores en la nube</button>`,'Guardar en la nube',async()=>{
    const submit=$('#dialog-form [type="submit"]');submit.disabled=true;submit.textContent='Guardando en la nube…';
    try{
      const saved=await privateClient().saveDraft(snapshot,snapshot.privateSavedAt);
      current.privateSavedAt=saved.privateSavedAt;save();privateLibrary.upsert(saved);close();toast('Guardado en la nube. Puedes abrir el borrador desde Borradores.');
    }catch(error){submit.disabled=false;submit.textContent='Reintentar guardado en la nube';throw error;}
  });
}
function openPrivateDraft(id){
  const remote=privateLibrary.state().posts.find(d=>d.id===id);if(!remote)return;
  save();
  const local=drafts.find(d=>d.id===id);
  const differs=local&&['title','markdown','html','cover'].some(key=>(local[key]||'')!==(remote[key]||''));
  const restore=()=>{
    if(differs){
      const backup=storeDraft(drafts,{...local,id:crypto.randomUUID(),slug:'',status:'draft',title:`${local.title||'Sin título'} (copia local)`,privateSavedAt:undefined});
      try{localStorage.setItem(STORAGE,JSON.stringify(backup));}catch{throw Error('No hay espacio para conservar tu copia local. Expórtala antes de abrir la versión privada.');}
      drafts=backup;
    }
    load({...remote,status:remote.originalStatus==='published'?'published':'draft'});save();close();toast('Borrador de la nube abierto. Los cambios se guardan localmente hasta que vuelvas a guardar una versión en la nube.');
  };
  if(differs)form('Abrir borrador de la nube',`<p>Esta copia es diferente de la que tienes en este navegador. Conservaremos tu versión actual como otro borrador local.</p>`,'Abrir borrador de la nube',restore);else restore();
}
function publishDialog(){syncSource();save();if(!current.title.trim()||editor.isEmpty){toast('Añade un título y contenido antes de publicar.');return;}const generatedSlug=slugify(current.title)||`articulo-${current.id.slice(0,8)}`;const locked=current.status==='published';const slugAttrs=`required pattern="[a-z0-9]+(-[a-z0-9]+)*" ${locked?'readonly':''}`;form(locked?'Actualizar artículo':'Publicar artículo',`<p>Tu artículo será público en el blog y en el repositorio de GitHub.</p>${field('Enlace del artículo','slug',current.slug||generatedSlug,'text',slugAttrs)}<label>Descripción para buscadores<textarea name="excerpt" maxlength="300">${esc(current.excerpt||'')}</textarea></label>${field('Etiquetas (separadas por comas)','tags',(current.tags||[]).join(', '))}<p class="hint">GitHub generará una página HTML y actualizará el índice del blog automáticamente. Puede tardar un par de minutos.</p><div id="publish-result" aria-live="polite"></div>`,'Publicar en mi blog',async data=>{if(saving)return;const api=client();saving=true;const submit=$('#dialog-form [type="submit"]');submit.disabled=true;submit.textContent='Publicando.';try{const {coverSource,coverCrop,privateSavedAt,originalStatus,...publishable}=current;const post={...publishable,updatedAt:new Date().toISOString(),author:settings.author,authorBio:settings.bio||'',authorHandle:settings.handle||settings.owner,slug:locked?current.slug:String(data.get('slug')),excerpt:String(data.get('excerpt')),tags:String(data.get('tags')).split(',').map(t=>t.trim()).filter(Boolean),status:'published',publishedAt:current.publishedAt||new Date().toISOString()};if(blogProfile.pending()){const profile=blogProfile.get();await api.saveProfile(profile);blogProfile.markPublished(profile);}const result=await api.publishPost(post);publishedLibrary.upsert(post);current={...post,...(privateSavedAt?{privateSavedAt}:{}),...(coverSource?{coverSource,coverCrop}:{})};save();$('.badge').textContent='Publicado';$('.save-state').classList.add('is-published');$('[data-action="publish"]').textContent='Actualizar';$('#publish-result').dataset.commit=result.commitSha;submit.hidden=true;renderPublication({status:'waiting'});pollDeployment(api,result.commitSha,{url:result.url,version:post.updatedAt});}catch(e){submit.disabled=false;submit.textContent='Reintentar publicación';throw e;}finally{saving=false;}});}
function renderPublication(state){
  const result=$('#publish-result');if(!result)return;
  const ready=state.status==='ready';
  const title=ready?'Tu artículo está publicado':state.status==='failed'?'No se pudo publicar la página':state.status==='pending'?'La publicación sigue en proceso':'Preparando tu artículo';
  const detail=ready?'La página está lista para abrirse y compartirla.':state.status==='failed'?'Tu artículo está guardado en GitHub. Revisa el despliegue antes de volver a enviarlo.':state.status==='pending'?'GitHub está tardando más de lo habitual. Puedes volver a comprobar sin publicar otra vez.':'Tu artículo está guardado. Estamos esperando a que la página esté disponible.';
  result.innerHTML=`<div class="publication-status" role="status"><span class="publication-icon ${state.status==='waiting'?'spinning':''}">${icon(ready?'check':state.status==='failed'?'circle-help':'cloud-upload')}</span><div><strong>${title}</strong><p>${detail}</p></div></div>${ready?`<a class="primary publication-open" target="_blank" rel="noopener" href="${esc(state.url)}">Ver artículo ${icon('arrow-up-right')}</a>`:''}${['pending','failed'].includes(state.status)?'<button type="button" class="outline wide" id="check-publication">Comprobar de nuevo</button>':''}${state.status==='failed'&&state.actionsUrl?`<a class="outline publication-open" href="${esc(state.actionsUrl)}" target="_blank" rel="noopener">Ver despliegue en GitHub</a>`:''}`;
  if($('#check-publication'))$('#check-publication').onclick=()=>{const p=result.publication;if(p)pollDeployment(p.api,p.sha,p.options);};
  refreshIcons();
}
async function pollDeployment(api,sha,options={}){
  const result=$('#publish-result');if(result){result.dataset.commit=sha;result.publication={api,sha,options};}
  await waitForPublication({api,sha,...options,onState:state=>{
    if($('#publish-result')?.dataset.commit===sha)renderPublication(state);
    if(state.status==='ready')toast(options.removed?'El blog se actualizó. El artículo ya no está publicado.':'Tu artículo ya está publicado.');
  }});
}
async function editCover(source,initial={}){
  modal('Editar portada',cropMarkup);
  try{await mountCoverCrop($('#modal-body'),source,(url,crop)=>{current.cover=url;current.coverSource=source;current.coverCrop=crop;renderCover();save();close();},initial);}catch{close();toast('No se pudo abrir la imagen. Elige otra portada.');}
}
async function readImage(file,isCover){if(!['image/png','image/jpeg','image/gif','image/webp'].includes(file.type))return toast('Usa una imagen PNG, JPEG, GIF o WebP.');if(file.size>2*1024*1024)return toast('La imagen debe pesar menos de 2 MB para guardarse en el navegador.');const url=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});if(isCover){await editCover(url);}else editor.chain().focus().setImage({src:url,alt:file.name}).run();}
function pickImage(isCover){const input=$('#file-input');input.accept='image/*';input.onchange=()=>{if(input.files[0])readImage(input.files[0],isCover);input.value='';};input.click();}
