function syncSourceFromText(){editor.commands.setContent(markdownWithMathBlocks($('#markdown-source').value),{contentType:'markdown',emitUpdate:false});scheduleSave();}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action],[data-draft],[data-emoji],[data-published],[data-private],[data-table]');if(!b)return;try{if(b.dataset.action)await actions[b.dataset.action]?.();else if(b.dataset.draft){save();load(drafts.find(d=>d.id===b.dataset.draft));close();}else if(b.dataset.private){openPrivateDraft(b.dataset.private);}else if(b.dataset.emoji){editor.chain().focus().insertContent(b.dataset.emoji).run();close();}else if(b.dataset.published){const post=published[Number(b.dataset.published)];save();load(publishedArticles([post],drafts).find(item=>item.id===post.id||item.slug===post.slug));close();save();}else if(b.dataset.table){editor.chain().focus()[b.dataset.table]().run();close();}refreshIcons();updateToolbar();}catch(error){toast(error.message);}});
$('#text-style').onchange=e=>{const v=e.target.value;v==='p'?editor.chain().focus().setParagraph().run():editor.chain().focus().toggleHeading({level:Number(v)}).run();};
$('#article-title').oninput=()=>{resizeTitle();scheduleSave();};$('#markdown-source').oninput=scheduleSave;
$('#md-input').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{save();const text=await file.text();if(file.name.endsWith('.json')){const imported=JSON.parse(text);if(!imported||typeof imported.title!=='string'||typeof imported.markdown!=='string')throw Error('El respaldo no tiene un formato válido.');load({...newDraft(),...imported,id:crypto.randomUUID(),html:DOMPurify.sanitize(imported.html||''),status:'draft'});}else{let title=file.name.replace(/\.[^.]+$/,'');let body=text;const match=text.match(/^# (.+)\r?\n/);if(match){title=match[1];body=text.slice(match[0].length);}load({...newDraft(),title,markdown:body});}save();toast('Artículo importado.');}catch(error){toast(error.message);}e.target.value='';};
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='s'){e.preventDefault();syncSource();save();toast('Borrador guardado.');}if(e.key==='Escape'&&!$('#modal').open)document.body.classList.remove('focus-mode');});
window.addEventListener('beforeunload',()=>{syncSource();save();});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
load(current);refreshIcons();
window.addEventListener('resize',resizeTitle);
// Column and focus-mode changes can resize the title without a window resize.
let titleWidth;
new ResizeObserver(([entry])=>{
  if(entry.contentRect.width!==titleWidth){
    titleWidth=entry.contentRect.width;
    resizeTitle();
  }
}).observe($('#article-title'));

